-- 16/11/2026 — Cidades e locais de Portis, Âmiem, Plana, Azanti, Cidades-Estado e Porto Livre.
--
-- Usuário: "Você terminou de criar todos os reinos e cidades do PDF? No reino
-- 'Cidades-Estado' faltam alguns. Por todo o mapa faltam vários." Fecha os
-- capítulos de tagmar/reinos.pdf que faltavam (3.8 Portis, 3.9 Âmiem, 3.12
-- Plana, 3.15 Azanti, 3.17 Cidades-Estado, 3.18 Porto Livre), escritos com a
-- skill cronista-de-tagmar. Nas Cidades-Estado, cada cidade é a sua própria
-- Cidade-Estado (Pino, Quízes, Ender, Novo Porto, Torbel, Estepe); a Liga não
-- tem capital. Idempotente: ON CONFLICT (slug) DO NOTHING; capital só se vazia.

BEGIN;

-- ── portis (novo-reino-h24-38047d95) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$runa$t$, $t$Runa$t$, $t$novo-reino-h24-38047d95$t$, true, NULL, $t$O conselho dos altos magos, regido pelo elfo dourado Iênim Calaudra, também regente da Escola Salius$t$, NULL, $t$O mercado de especiarias, no lado oriental da cidade, é o coração do comércio do reino: tendas a perder de vista, à maneira lévana, e mercadores de todos os reinos neutros. Quem busca algo raro, acha ali.$t$, $t$Capital de Portis, fundada por volta de 194 D.C. sobre ruínas mais antigas. Em pouco mais de trinta anos de magocracia, a cidade trocou a velha cara pelas torres altas de cores vivas dos magos regentes, sem respeito nenhum pelo passado.
No centro, as torres do governo ficam numa ilha artificial sob uma redoma de energia de natureza desconhecida, e só quatro pontes em arco levam até lá. Guardam-nas a Guarda Arcana, os melhores guerreiros do reino, que andam de cinco em cinco em volta de cada mago regente e respondem só a eles, sob tenentes que são magos. Perto dali fica a Escola de Arquitetura, dos maiores magos elementais do reino, regida por Melvim.
Com um exército fraco e magos que não olham para quem não é místico, as guildas de ladinos ganharam folga. Com astúcia para não atrair a ira dos regentes, fazem bons negócios na capital.$t$, $t$Corre que no mercado negro de Runa há quem venda tudo o que um ritual necromântico pede, até cadáveres por encomenda, para compradores bem recomendados.
Dizem que no conselho dos magos há uma cadeira oculta, ocupada por um necromante poderoso o bastante para impor a própria presença. Quem fala demais disso some.$t$, false),
($t$maginor$t$, $t$Maginor$t$, $t$novo-reino-h24-38047d95$t$, false, NULL, NULL, NULL, $t$Vive dos estudiosos e das expedições a Luna: muitas hospedarias para todo bolso, e um mercado de papiro, pena, tinta, mapas, cordas e ganchos a bom preço — dizem que até bússolas. Armas e armaduras são raras e caras; há pelo menos dois ferreiros na cidade.$t$, $t$Uma das cidades mais antigas de Portis e hoje a mais decadente. Já foi a maior e mais importante do reino, mais que a capital. Nasceu de tribos portinenses e lunenses que se assentaram em feudos, e daí veio a arquitetura mais singular do reino, herança de tempos esquecidos.
Sofreu mais que todas com o golpe da magocracia: o Duque de Maginor morreu na revolta, os parentes fugiram, e a cidade ficou com a sensação de abandono. As famílias mais antigas e os costumes tradicionais ainda resistem aqui. Hoje é mais sítio arqueológico que cidade, com mais bibliotecas que tabernas, e é o ponto de partida das incursões a Luna.$t$, $t$Fala-se de um colégio clandestino de magia necromântica em Maginor, escondido entre os becos que fazem da cidade um labirinto e nos casarões que os nobres abandonaram.$t$, false),
($t$estenorial$t$, $t$Estenorial$t$, $t$novo-reino-h24-38047d95$t$, false, NULL, NULL, $t$Sevides, com um grande templo; Liris e Quiris, com templos mais modestos$t$, $t$O coração agrícola de Portis: daqui sai cerca de sessenta em cem de tudo o que se come no reino, e muito mais vai para fora quase todo dia. Boa parte do que ainda chega às bocas de Luna passa por Calisto vindo daqui.$t$, $t$A maior área de lavoura do reino, que o povo diz abençoada por Sevides. A gente é humilde, de camponeses e artífices simples; com a saída da nobreza, a cidade tomou ainda mais terras rurais.
Há tantos sacerdotes de Sevides, Liris e Quiris que muitos acham exagero; o povo vê nisso bênção a mais. Os altos sacerdotes de Sevides gastam toda a sua ciência para segurar a praga de Luna na fronteira e manter verdes os campos de Estenorial. Até agora conseguem, mas o próprio clero se pergunta até quando.$t$, $t$Correm histórias de uma busca sem fim por itens de grande poder que ajudem os sacerdotes contra a praga.
O medo da peste é tanto que o povo de Estenorial seria capaz de linchar em praça pública qualquer refugiado de Luna.$t$, false),
($t$tanus$t$, $t$Tanus$t$, $t$novo-reino-h24-38047d95$t$, false, NULL, NULL, $t$Blator começa a ganhar força na cidade$t$, $t$Fazendas fartas ao norte, que ajudam a encher as mesas do reino, e um comércio de especiarias mais caro que o das cidades do sul. Com estradas ruins e a capital difícil de alcançar entre montanhas, os fazendeiros preferem vender para Estepe e para as Cidades-Estado.$t$, $t$Cidade do noroeste de Portis, nem tão agrícola quanto Estenorial nem tão moderna quanto Runa. As rotas são longas e cheias de salteadores, e o relevo acidentado até a capital encarece tudo o que sai daqui.
As incursões de Azanti explodem com frequência nos seus portões. O povo, que não é de guerreiros, aprende a lutar por necessidade, reclama da capital que nada faz, contrata mercenários das Cidades-Estado e já pensa numa muralha com fosso.$t$, $t$Dizem que o Duque de Azanti já traçou planos para tomar Tanus, peça-chave de uma guerra contra Portis, e que suas tropas sairiam de Fétor, atravessando o Lara.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$planalto-de-runa$t$, $t$Planalto de Runa e Montes Raltril$t$, $t$novo-reino-h24-38047d95$t$, NULL, $t$O planalto no centro de Portis, onde ficam os montes Raltril. Ali o clima é tropical de montanha, frio e úmido, e no cume dos montes há o que chamam de gelo eterno. A mata, densa na beira do Lara, vai abrindo à medida que se sobe o planalto.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$runa$t$ WHERE slug = $t$novo-reino-h24-38047d95$t$ AND capital IS NULL;

-- ── âmiem (novo-reino-h13-f117a8ed) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$marna$t$, $t$Marna$t$, $t$novo-reino-h13-f117a8ed$t$, false, NULL, NULL, $t$Templos de vários deuses e ordens de muitos deles$t$, $t$O vidro de Marna, leve e resistente, famoso no mundo inteiro; em placas finas, faz os vitrais mais pedidos pelos templos. As encomendas são caras, e a cidade prospera sem perder a beleza.$t$, $t$Cidade nascida em volta da Torre da Marna, a mais alta e bela das Torres Guardiãs, na entrada do Vale de Vandril, ao pé do desfiladeiro. Toda em granito amarelo, lembra os dias gloriosos de Lar, o primeiro reino daqueles elfos.
Tem tudo de uma cidade grande: bibliotecas, museus, escolas onde se ensina do alfabeto élfico à filosofia, um belo teatro, uma filial do colégio elemental — em crise e vista com suspeita desde o cisma — e, entre fontes e jardins, a mais bela filial do colégio ilusório. Ali se reúnem todo mês rastreadores elfos de muitos cantos do mundo, e a Confraria Olhos de Águia forma bardos de baladas, danças e contos élficos.
Da cidade parte a velha estrada calçada que percorre o vale até as ruínas da Torre de Enor. Dizem que nas ruas se veem pequeninos e até alguns humanos.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-edelnur$t$, $t$Floresta de Edelnur$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$Começa em Âmiem e só termina na Levânia: a mais densa das florestas do reino e a menos habitada pelos elfos. Guardam-na a rede de ilusões e a Torre de Edelnur, escondida num ponto secreto, de onde saem as patrulhas. O único povoado digno de nota é uma comunidade de centauros.
No extremo sul, onde encontra a floresta de Brindel, ficam a Torre Oculta e o velho centro comercial de Talco. É ali que se juntam mais ilusões, e o lugar é sagrado para Âmiem, porque guarda a Ponte de Palier.$t$, $t$Dizem que a escola necromântica ergueu uma base na floresta e recruta adeptos, e quem anda sozinho ao crepúsculo fala de sombras estranhas. Há quem ligue essas sombras ao cristal onde Morrigalti foi preso.$t$, false),
($t$talco$t$, $t$Talco$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$Antigo centro comercial no extremo sul de Edelnur, perto da Torre Oculta. Nasceu com a fundação da escola alquímica e chegou a ser chamado de cidade. Hoje está quase abandonado.$t$, $t$Dizem que a escola de magia quer se mudar de Talco para Marna.$t$, false),
($t$floresta-de-laudis$t$, $t$Floresta de Laudis$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$Na fronteira de Âmiem com Ludgrim, uma das florestas mais místicas de Tagmar. O ar vive cheio de partículas douradas: o pólen da flor Laudis, que dá nome à mata. Quem o respira tem os sentidos trocados e cai em delírios, e por isso nenhum ser racional mora ali.
Mesmo assim muitos entram atrás do pólen, de que se faz o pó de Laudis, conhecido em todo o mundo por servir às magias ilusórias. Da raiz da flor saem boas poções alucinógenas e anestésicas.$t$, $t$Aventureiros que passam muito tempo ali contam de um grande grifo que fala dentro da cabeça das pessoas, sem abrir o bico, e manda que se afastem de uma árvore de brilho dourado. Há também a lenda da Sala de Palier, que guardaria dois dragões presos sob a mata.$t$, false),
($t$floresta-de-melram$t$, $t$Floresta de Melram$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$Na divisa de Âmiem com Verrogar e Eredra, a maior parte do lado verrogari. Discórdia de séculos entre os três reinos, acabou dividida em três. A parte de Âmiem foi devastada na guerra da Seita, e os povoados élficos minguam com os incidentes cada vez mais frequentes, sobretudo com os verrogaris, e com as feras que atravessam a fronteira.
O príncipe Gáltilo II incentiva a construção de pequenas torres na borda da floresta. A Torre de Melram, a mais nova das guardiãs, lida com mais gente tentando entrar escondida no reino do que todas as outras.$t$, $t$Corre que Verrogar solta feras na floresta para atingir Âmiem, e que magos mercenários criam monstros para soltar ali. Sacerdotes de Maira veem nas feras uma resposta da deusa ao avanço da cidade.$t$, false),
($t$floresta-de-brindel$t$, $t$Floresta de Brindel$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$O coração de Âmiem. No centro, as árvores chegam a tamanhos gigantescos, e nas copas fica a Cidade Dourada, cujo lugar exato poucos elfos sabem. Além dela há outras cidades nas copas e comunidades nômades que vivem ao pé das árvores.$t$, NULL, false),
($t$vale-de-vandril$t$, $t$Vale de Vandril$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$A parte mais povoada de Âmiem: vilas e aldeias entre bosques, sítios e plantações de seda. Vai das encostas das montanhas Sharar ao extremo sul de Edelnur, como um corredor entre Brindel e Edelnur, e nele ficam as Ruínas de Enor.
Aqui se fazem as finas rendas élficas que vestem a nobreza do mundo. Aqui também vive o clã que guarda o segredo do candelie, brocado de seda com fios de ouro ou prata, o tecido mais belo e caro de Tagmar.$t$, $t$Dizem que o segredo do candelie está nas mãos de dois irmãos que andam brigando, e não falta mercador querendo descobri-lo.$t$, false),
($t$montanhas-sharar$t$, $t$Montanhas Sharar$t$, $t$novo-reino-h13-f117a8ed$t$, NULL, $t$Fronteira natural entre Âmiem, Levânia e Ludgrim. São frias, de inverno duro e nevascas constantes, e as moradas são raras e isoladas. No sopé ficam os pomares de candre, uma noz que, moída, dá a farinha fina das massas folhadas élficas.$t$, $t$Rastreadores dizem que certas construções nas montanhas seriam lugares de sacrifício de uma raça que viveu ali há séculos. E há quem jure que o cristal onde Morrigalti foi preso está numa caverna das Sharar.$t$, false)
ON CONFLICT (slug) DO NOTHING;

-- ── plana (novo-reino-h24-e74de213) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$caleonir$t$, $t$Caleonir$t$, $t$novo-reino-h24-e74de213$t$, true, NULL, $t$O Conselho Maior; é a única cidade grande sem Conselho Menor$t$, NULL, $t$O maior porto de Plana, de troca, compra e venda: acha-se de tudo, do trigo de Eredra ao artesanato das terras bárbaras.$t$, $t$Capital de Plana e o retrato do reino. Enquanto as outras cidades se repartem em especialidades, Caleonir é a mais variada de todas.
Aqui ficam o Conselho Maior, a sede de recrutamento dos mercenários conhecidos como Capitães-Juízes, que dali recebem a sua área, e o centro do exército planense.$t$, NULL, false),
($t$aradelis$t$, $t$Aradelis$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, NULL, NULL, $t$A maior praça de artigos finos de Plana: seda, ourivesaria, joias e peças de arte.$t$, $t$Uma das cidades mais antigas do reino, fundada logo depois de Plana. Foi o berço da nobreza que coroou Azaias I, o primeiro soberano, até que os grandes mercadores, achando a monarquia pouco lucrativa, a depuseram.
Deixou de ser cidade de nobres, mas guardou a tradição. É tida como uma das mais belas de Plana, com estalagens e tabernas requintadas, iguarias de todo tipo e os melhores vinhos do mundo.$t$, NULL, false),
($t$porto-velho$t$, $t$Porto Velho$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, $t$O Conselho Menor de Porto Velho, o mais influente de Plana$t$, NULL, $t$O segundo porto do reino, com casas de iguarias do mar e artigos de caça e pesca. Aqui se faz o melhor Portrice Azul de Plana, das ovas dos esturjões azuis que passam pela costa todo ano — uma das iguarias mais caras que há.$t$, $t$Tão antigo quanto a capital, foi o primeiro porto de Plana. Quando o governo mudou e Caleonir virou capital, os mercadores fizeram lá o porto maior, e Porto Velho ficou em segundo.
A rivalidade nunca acabou: o Conselho Menor daqui é o mais influente de todos, e muitas vezes dobra a vontade dos conselheiros de Caleonir.$t$, NULL, false),
($t$balistro$t$, $t$Balistro$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, NULL, NULL, $t$Catapultas grandes e precisas e outras armas de cerco; toda sorte de arma e armadura, com armeiros, ferreiros e mestres de armas prontos para vender ou ensinar — pelo preço certo. Também constrói as embarcações do reino e de quem quiser comprar.$t$, $t$Quase uma cidade militar, a cidade das armas. É aqui que treina a maior parte do exército de Plana, e daqui partem milícias treinadas para todo o reino. Sedia as Academias de Guerreiros e responde pela guarda do mar planense.$t$, $t$Muitos aventureiros correm para Balistro e Pórtis para entrar na milícia marítima, à espera de uma guerra contra os piratas de Porto Livre.$t$, false),
($t$omarge$t$, $t$Omarge$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, NULL, NULL, $t$Um grande mercado a céu aberto, ponte do comércio com Bassani e Saravossa, em Calco: grãos, cereais, frutas secas, carne seca, queijos, sal, rações para viagem e temperos. O mercado de temperos exóticos da praça principal é famoso, e a cidade faz queijos, manteigas, leite e iogurte.$t$, $t$O centro comercial de Plana na direção de Calco, por onde passa quase tudo o que dura muito tempo guardado.$t$, NULL, false),
($t$cipa$t$, $t$Cipa$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, NULL, NULL, $t$A maior e melhor cervejaria de Plana, talvez do mundo, com uma das jarras mais caras que há. Nas margens do rio Cipa crescem grandes pomares, entre eles o da rara fruta-cipa, rosada como cereja e do tamanho de uma laranja; o doce dela vai para as mesas nobres do mundo inteiro.$t$, $t$Cidade numa terra abençoada, à beira do rio Cipa, de cervejarias lendárias e pomares fartos.$t$, NULL, false),
($t$alimar$t$, $t$Alimar$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, NULL, NULL, $t$Posto avançado do comércio por terra com o sul — Levânia, Âmiem e Ludgrim — e um dos poucos mercados abertos do mundo para as curiosidades, estranhas e até mágicas, trazidas das expedições a Abadom.$t$, $t$Cidade à margem do rio Mam, bem fortificada e guardada pelo dobro da milícia de costume, por estar perto de Abadom e da Cordilheira de Sotopor. Sempre parte daqui alguma caravana pelas terras inóspitas de Abadom rumo à Levânia, e por isso batedores e soldados são mais procurados que em qualquer lugar.$t$, NULL, false),
($t$portis-plana$t$, $t$Pórtis$t$, $t$novo-reino-h24-e74de213$t$, false, NULL, $t$O Conselho Menor de Pórtis$t$, NULL, $t$Todo o comércio de Plana com os reinos do Lago Denégrio — Calco, Conti, Filanti e Verrogar — passa por aqui, e acha-se quase tanto quanto na capital. As planícies em volta, muito férteis, guardam boa parte da lavoura e da criação do reino.$t$, $t$Cidade à beira do Lago Denégrio. Atenção ao acento: não é o reino de Portis, e confundir os dois magoa o povo de Pórtis — o que costuma ser ruim para os negócios.$t$, $t$Navios que saem de Plana para cruzar o Denégrio somem sem explicação, e nos portos se fala de dragões e criaturas aladas descendo da Cordilheira de Sotopor.$t$, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$caleonir$t$ WHERE slug = $t$novo-reino-h24-e74de213$t$ AND capital IS NULL;

-- ── azanti (novo-reino-h24-f4ecad3b) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$zanta$t$, $t$Zanta$t$, $t$novo-reino-h24-f4ecad3b$t$, true, NULL, $t$O Duque Lenor, o Diplomata$t$, NULL, $t$Perto do portão norte fica o Curtume do Velho, que faz o melhor couro de Azanti — o cheiro é horrível, o serviço é excelente e o preço costuma ser justo.$t$, $t$A maior, mais rica e mais importante cidade de Azanti, erguida há mais de quinhentos anos. No alto de uma colina, no centro, fica o castelo do Duque e da sua família; em volta, as casas e lojas das famílias ricas e a Taberna da Colina Real, onde ninguém entra armado, a não ser o Duque e a sua guarda.
A parte sul é a mais pobre, de ruas sujas e bandidos em cada beco. À noite, quando a cidade dorme, os ladrões e assassinos começam a trabalhar.$t$, $t$Dizem que ainda há em Zanta guerreiros da Ordem de Crizagom, encarregados de contar aos mestres tudo o que acontece dentro dos muros, e que Sir Corelom estaria por trás de um golpe para derrubar o Duque.$t$, false),
($t$mirval$t$, $t$Mirval$t$, $t$novo-reino-h24-f4ecad3b$t$, false, NULL, $t$O Barão de Mirval$t$, NULL, NULL, $t$Cidade ao sul de Zanta, perto da fronteira com Filanti, de povo muito variado. O Barão é conhecido pela mania de casar: tem hoje sete mulheres e quinze filhos. É um homem bom, sempre de bom humor, disposto a ajudar quem pede, e fiel ao Duque Lenor.
A leste fica o Lago da Sereia, formado por uma queda d'água que desce da Cordilheira de Keiss.$t$, $t$Há quem diga que o Barão é da Seita e se aproximou do Duque por ordem de Ludur, conselheiro de Filanti. O povo de Mirval, que admira o Barão, toma o boato como ofensa pessoal.$t$, false),
($t$grabo$t$, $t$Grabo$t$, $t$novo-reino-h24-f4ecad3b$t$, false, NULL, $t$O Visconde Sívas$t$, $t$Há quem ainda faça oferendas à estátua do Guerreiro sem Nome$t$, NULL, $t$Cidade nascida em volta de uma estátua de pedra achada numa exploração: um homem de couraça parcial, espada e escudo. O povo a tomou por Crizagom e foi erguendo casas ao redor. Os sacerdotes do deus desmentiram, e ela virou o Guerreiro sem Nome, mas ainda há quem lhe sussurre orações.
O Visconde Sívas, homem de meia-idade e passado sangrento, recebeu o título do Duque Euridi, a quem serviu com fidelidade. É inimigo ferrenho do Duque Lenor, que ele culpa até hoje pela morte de Euridi.$t$, $t$Há quem diga que a estátua é um antigo sacerdote de Crizagom que se deixou corromper e foi transformado em pedra pelo próprio deus.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$lago-da-sereia$t$, $t$Lago da Sereia$t$, $t$novo-reino-h24-f4ecad3b$t$, NULL, $t$Grande lago a leste de Mirval, formado por uma queda d'água da Cordilheira de Keiss. Conta a lenda que Miriam, casada com um bravo guerreiro da cidade, fugiu com o amante para as montanhas; o marido os alcançou, o amante escapou, e ela morreu afogada no lago. Desde então dizem que ela confunde os homens com o seu amor e os mata nos seus braços de água.
Estudiosos falam em lenda, mas onze pessoas morreram ali nos últimos dez anos — todas homens.$t$, $t$Há quem diga que o lago é morada de uma ninfa, que atrai os homens e mata os que resistem ou tentam fugir.$t$, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$zanta$t$ WHERE slug = $t$novo-reino-h24-f4ecad3b$t$ AND capital IS NULL;

-- ── cidades-estado (novo-reino-h24-d82a4d49) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$pino$t$, $t$Pino$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$Ivanna Puni, oligarca e comandante de todo o exército$t$, $t$Blator e Crezir por lei; Cambu entre os Kaliaka e Ganis entre os Toredo. O culto a Selimom é mantido em segredo.$t$, $t$Óleos vegetais e palmito, tirados das árvores da região, queijos de cabra e de vaca, boa pesca e uma mineração que cresce. O que sobra é trocado com Conti e Plana.$t$, $t$A Cidade-Estado do noroeste, entre o Mar do Norte, Conti, Quízes e Novo Porto, de clima mais ameno que as outras. Toda a lavoura fica ao longo do rio Branco, que desce da Serra de Pino.
Duas oligarquias se enfrentaram por gerações: os Toredo, humanos, donos das terras, da lavoura e da pesca, e os Kaliaka, elfos vindos de Conti, artífices e mercadores. As guerras entre elas e contra Conti deram a Pino o maior exército das Cidades-Estado e um povo com gosto pelo combate, que desconfia de estrangeiro. Pino foi a primeira a propor a Liga, é a que mais manda nela, e forma quase todos os generais das outras.
A paz veio com Ivanna Puni, meia-elfa filha das duas oligarquias, que esmagou uma revolta de escravos e governa com mão de ferro.$t$, $t$Pino cortou relações com Novo Porto quando Lorde Alstus subiu ao poder. Dizem que um dos oligarcas que ele derrubou, Auliz Mecenas, era amante de Ivanna, e que soldados e nobres de Conti circulam cada vez mais pela cidade por causa de acordos ainda secretos.$t$, false),
($t$quizes$t$, $t$Quízes$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$O Ditador Azedi Sadi, vigésimo terceiro depois de Aradi$t$, $t$Cambu, que deu a fonte; Maira Mon$t$, $t$Entreposto das rotas por terra de Conti, Azanti, Filanti e Portis, e oficina de vidro, cerâmica e cristal conhecidos em toda Tagmar.$t$, $t$Cidade-Estado de clima seco, semiárido, com um centro de deserto, cercada de montanhas. Nasceu numa fonte que a abastece até hoje. Conta a lenda que Aradi Isael, sacerdote de Cambu banido do seu reino, vagava faminto pelo deserto quando um enviado do deus pisou o chão e fez a água brotar da pedra.
Os oligarcas dizem descender dele e serem donos de Quízes por direito divino. O povo, servo ou livre, passa fome e doença no meio da prosperidade, e as mulheres humanas vivem em servidão a pais e maridos. As disputas de terra com Ender e Novo Porto fazem a cidade encher-se de mercenários, e um movimento de sacerdotes de Cambu que contesta a santidade da oligarquia cresce, perseguido como heresia.$t$, $t$Dizem que sacerdotes de Cambu se aliaram a gente de Torbel para um ataque, e que o oligarca Seldi, expulso com a família, forma uma resistência fora da cidade. Bandos armados saqueiam vilas na fronteira com Ender e levam escravos, e cada cidade culpa a outra.$t$, false),
($t$ender$t$, $t$Ender$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$Dario de Marum, o oligarca mais velho, com o conselho dos anciãos dos clãs$t$, $t$Todos os deuses, organizados pela oligarquia Nariska: Maira Mon e Parom nas montanhas, Sevides, Quiris e Liris junto ao Edaim, Cambu e Blator na fronteira com Quízes, Selimom na capital$t$, $t$A economia mais variada das Cidades-Estado: minério da Serra de Ender, cereais, pesca e vinhas à beira do Edaim, criação junto aos Montes Basilor, couro, lã e laticínios. As vilas do deserto fazem armas compradas em todas as Cidades.$t$, $t$A Cidade-Estado do sul, com o rio Edaim a leste. Diz a lenda que Adessa Elifa chegou sozinho e fundou Ender — "terra final" —, e antes de morrer dividiu as terras e as missões entre os seus treze filhos, que viraram os treze clãs. A Nariska, que leva o nome da única filha, cuida da capital e não produz nada: vive do dami, a doação dos outros clãs.
Vive a maior prosperidade da sua história, paga o melhor soldo das Cidades e trata bem o povo — menos quem tem parentes nascidos em Quízes. Só criminosos, cativos de guerra e devedores podem ser escravos. Mas as terras dos clãs já não bastam para as famílias novas, e a ideia de crescer sobre os vizinhos ganha força, sobretudo entre os Marum, Zipare e Silpem.$t$, $t$Fala-se de um culto ao Mais Sábio crescendo em Ender, que o tem por união de todos os deuses e diz que ele volta de tempos em tempos no corpo de um homem — heresia em toda Tagmar.$t$, false),
($t$novo-porto$t$, $t$Novo Porto$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$O Lorde Alstus, ditador$t$, $t$Ganis e Cambu; Crezir e Blator crescem desde Alstus. O culto a Lena é proibido.$t$, $t$Parada obrigatória dos navios entre o Mundo Conhecido e as Ilhas Independentes: tecidos, joias, especiarias, armas e bebidas das ilhas só se vendem aqui. A comida, cheia de sabores das ilhas, é das mais famosas do mundo.$t$, $t$A Cidade-Estado do norte, semiárida, entre o Mar do Norte, os Montes Basilor, Torbel, Pino, Quízes e Ender. Lorde Alstus tomou o poder numa batalha violenta contra a velha oligarquia, ligada por sangue à de Pino, e governa na ditadura mais desconfiada das Cidades, de vigilância política e cultural extrema.
Estudiosos de toda Tagmar vêm aos sítios de pesquisa da Segunda Era e à Biblioteca Santa, uma das maiores do mundo, juntada por um homem só, Lutus Virel, hoje com uns noventa anos. O povo fala baixo — falar alto é vulgar —, e quem entra numa taberna ouve só sussurros.$t$, $t$Dizem que o golpe final de Alstus foi misturar plantas venenosas às ervas das ilhas que a velha oligarquia usava nos cultos a Lena, e que o tráfico dessas ervas, hoje proibidas, continua e se espalha pelo mundo.$t$, false),
($t$torbel$t$, $t$Torbel$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$O conselho democrático, com o Escrivão-Chefe Calamar Orlença, o Grande-Juiz Samos de Liria e o Executor-Chefe Malori Alduias$t$, $t$Maira Vet, Cambu, Ganis e, num culto novo, Selimom$t$, $t$A maior construtora de navios do Mundo Conhecido nos últimos cinquenta anos — dizem que até Verrogar comprou navios de guerra daqui —, madeira e tintas naturais, e pesca. Não colhe o bastante e depende de Estepe.$t$, $t$A Cidade-Estado cercada pelos Montes Basilor, entre Estepe, Ender, Novo Porto e o Mar do Norte, com os climas mais variados: quase mediterrâneo no litoral, frio e seco nos montes, semiárido no noroeste. O rio Calmo corta a capital ao meio e leva quase tudo de um lado a outro.
Depois de derrubar os ditadores, os oligarcas e as outras castas fundaram uma democracia: nobres e grandes mercadores votam as leis no Salão Comunal. É a menor das populações, toda no Vale do Segredo — Torbel quer dizer segredo na língua bárbara —, e a mais culta, mestra em náutica, astrologia, escultura e pintura. A casta pode mudar com a riqueza, mas as mulheres de todas as raças ainda são tratadas como inferiores.$t$, $t$Dizem que nos montes há os restos de uma cidade inteira do Segundo Ciclo, em terra amaldiçoada de onde ninguém sai, e que um velho nobre vive lá como vampiro. Fala-se também que as outras Cidades se juntam contra Torbel, com medo da democracia.$t$, false),
($t$estepe$t$, $t$Estepe$t$, $t$novo-reino-h24-d82a4d49$t$, false, NULL, $t$O Lorde Menelau, o maior dono de terras da região$t$, $t$Sevides, Cambu e Ganis, com os maiores templos; Blator, Crizagom e Crezir só têm um templo cada, na mansão do Lorde$t$, $t$A maior lavoura das Cidades-Estado, de cereais, nas margens do Lara e do Edaim, e tecidos, tapetes e tapeçarias vendidos ao mundo inteiro, sobretudo a Plana.$t$, $t$A Cidade-Estado do sudeste, com o Lara ao sul, na divisa com Portis, e o mar a leste. De clima ameno e terra boa, é a que mais precisa de servos e escravos, e quase todo o povo serve a algum oligarca. Só a oligarquia e o exército andam armados.
O Lorde Menelau, sucessor do pai, cuida de estradas entre as Cidades, da defesa do mar — que boa parte vem de Torbel — e da luta contra revoltosos. Por estar mais perto de Porto Livre, é a costa mais patrulhada pelos navios das Cidades.$t$, $t$Dizem que as terras perdem a força pelo uso sem cuidado, e que os oligarcas dobram as oferendas a Sevides. O líder dos revoltosos é Fidelis, filho de um oligarca, tido como seguidor da Seita; há quem diga que ele recebe ajuda de Torbel.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$serra-de-pino$t$, $t$Serra de Pino$t$, $t$novo-reino-h24-d82a4d49$t$, NULL, $t$Serra de onde desce o rio Branco, ao longo do qual fica toda a terra de plantar de Pino.$t$, NULL, false),
($t$serra-de-ender$t$, $t$Serra de Ender$t$, $t$novo-reino-h24-d82a4d49$t$, NULL, $t$Montanhas na fronteira de Ender com Azanti, terras dos clãs Garak e Ronal. Dali Ender tira o seu minério, e nas vilas da serra Maira Mon e Parom são os deuses mais cultuados.$t$, NULL, false),
($t$montes-basilor$t$, $t$Montes Basilor$t$, $t$novo-reino-h24-d82a4d49$t$, NULL, $t$Cadeia de montes que ocupa a maior parte de Torbel e separa Novo Porto, Ender e Estepe. No alto o clima é frio e seco, bom para os sildares, árvores de madeira macia; nas encostas de Ender vive a criação de gado. Faltam estradas entre os montes, e por isso a busca de minério anda devagar.$t$, $t$Dizem que anões exploram a cadeia do lado de Estepe, mas nenhuma grande jazida foi achada até agora.$t$, false)
ON CONFLICT (slug) DO NOTHING;

-- ── porto livre (novo-reino-h24-0b048426) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$quessedir$t$, $t$Quessedir$t$, $t$novo-reino-h24-0b048426$t$, true, NULL, $t$Os sete Barões, com poder igual; nenhum manda sozinho$t$, NULL, $t$Território neutro de compra e venda: é aqui que os piratas negociam a sua parte no butim e gastam o que ganharam.$t$, $t$A pérola do leste, capital de Porto Livre. Não é terra de ninguém: é terra de todo mundo — ao menos dos que importam, os Barões. Por muito tempo o comando passou de Barão em Barão a sangue, até que, depois de Melkair quase arrancar a cabeça de Ulisses numa dessas disputas, um concílio de paz decidiu que nenhum Barão mandaria sozinho em Quessedir.
As terras foram divididas em sete baronatos, e Quessedir ficou como o ponto neutro entre eles. Quando estão em terra, os Barões passam quase todo o tempo aqui, cada um numa das sete construções magníficas da cidade. O forasteiro só entra livre em Quessedir; nos baronatos, só com salvo-conduto selado, e quem é pego sem ele raramente sai.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$quessedir$t$ WHERE slug = $t$novo-reino-h24-0b048426$t$ AND capital IS NULL;
-- Os recifes da costa porto-livrense (criados sem reino em 15/11) passam a ser de Porto Livre.
UPDATE public.locais SET reino = $t$novo-reino-h24-0b048426$t$ WHERE slug IN ($t$recifes-de-gandara$t$, $t$recifes-do-tubarao$t$) AND reino IS NULL;

-- Âmiem: a Cidade Dourada, onde fica a casa real, é a capital.
UPDATE public.reinos SET capital = 'nova-cidade-h13-10d68e1c' WHERE slug = 'novo-reino-h13-f117a8ed' AND capital IS NULL;
UPDATE public.cidades SET capital = true WHERE slug = 'nova-cidade-h13-10d68e1c' AND NOT capital;

COMMIT;
